python3 - <<'EOF'
PATH='/home/lane/MythosMini/slm_alliance.html'
src=open(PATH).read()

old='''<filter id="logoBoil" x="-10%" y="-10%" width="120%" height="120%">
        <feTurbulence type="turbulence" baseFrequency="0.0028" numOctaves="1" seed="1" result="noise"/>
        <feDisplacementMap in="SourceGraphic" in2="noise" scale="38" xChannelSelector="R" yChannelSelector="G"/>
      </filter>'''
new='''<filter id="logoBoil" x="-15%" y="-15%" width="130%" height="130%">
        <feTurbulence type="turbulence" baseFrequency="0.0028" numOctaves="1" seed="7" result="bendNoise"/>
        <feOffset in="bendNoise" dx="0" dy="0" result="bendShifted" id="bendOffset"/>
        <feDisplacementMap in="SourceGraphic" in2="bendShifted" scale="24" xChannelSelector="R" yChannelSelector="G" result="bent"/>
        <feTurbulence type="turbulence" baseFrequency="0.013" numOctaves="1" seed="3" result="texNoise"/>
        <feOffset in="texNoise" dx="0" dy="0" result="texShifted" id="texOffset"/>
        <feDisplacementMap in="bent" in2="texShifted" scale="9" xChannelSelector="R" yChannelSelector="G"/>
      </filter>'''
assert old in src
src=src.replace(old,new)

start=src.index('        // Boil: flip to a new random pose ~5x/sec, like a hand-drawn flipbook.')
end=src.index('        // Hold the intro until the logo scrolls into view.')
new_js='''        // Boil with memory: each frame is a small mean-reverting random step
        // away from the last pose, so redraws stay near the average line.
        if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
          const bend = svg.querySelector('#bendOffset');
          const tex = svg.querySelector('#texOffset');
          const walk = { bx: 0, by: 0, tx: 0, ty: 0 };
          const step = () => (Math.random() * 2 - 1);
          setInterval(() => {
            // Ornstein-Uhlenbeck: pull back toward 0, nudge randomly.
            walk.bx = walk.bx * 0.7 + step() * 90;
            walk.by = walk.by * 0.7 + step() * 90;
            walk.tx = walk.tx * 0.7 + step() * 30;
            walk.ty = walk.ty * 0.7 + step() * 30;
            bend.setAttribute('dx', walk.bx.toFixed(1));
            bend.setAttribute('dy', walk.by.toFixed(1));
            tex.setAttribute('dx', walk.tx.toFixed(1));
            tex.setAttribute('dy', walk.ty.toFixed(1));
          }, 190);
        }

'''
src=src[:start]+new_js+src[end:]
open(PATH,'w').write(src)
print('OK')
